async function throttleQueue(tasks, interval) {
    const results = [];

    // Iterate over the tasks array
    for (let i = 0; i < tasks.length; i++) {
        // Wait for the previous task to complete and the interval to pass
        if (i > 0) {
            await new Promise((resolve) => setTimeout(resolve, interval));
        }

        try {
            // Run the current task and store its result
            const result = await tasks[i]();
            results.push(result);
        } catch (error) {
            // Handle any task failure (optional)
            console.error(`Task ${i} failed:`, error);
            results.push(null); // Push null for failed task, or handle differently
        }
    }

    return results;
}

